function tribonacci(n) {
  if (n === 0) return 0;
  if (n === 1) return 0;
  if (n === 2) return 1;
  let t0 = 0, t1 = 0, t2 = 1;
  for (let i = 3; i <= n; i++) {
    const next = t0 + t1 + t2;
    t0 = t1;
    t1 = t2;
    t2 = next;
  }
  return t2;
}

sampleSolution.python:
def tribonacci(n):
    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 1
    t0, t1, t2 = 0, 0, 1
    for _ in range(3, n + 1):
        t0, t1, t2 = t1, t2, t0 + t1 + t2
    return t2
